def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def value(row, key):
        item = row.get(key, "")
        return "" if item is None else str(item)

    def normalize_email(raw):
        text = value({"v": raw}, "v").strip()
        match = re.search(r"<([^<>]*)>", text)
        if match:
            text = match.group(1)
        text = text.strip().lower()

        if text.count("@") != 1:
            return ""
        local, domain = text.split("@")
        if not local or not domain or "." not in domain or domain.startswith(".") or domain.endswith("."):
            return ""

        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            if not local:
                return ""
            domain = "gmail.com"

        return f"{local}@{domain}"

    def normalize_phone(raw):
        text = value({"v": raw}, "v")
        match = re.search(r"x|ext|#", text, flags=re.IGNORECASE)
        if match:
            text = text[:match.start()]
        digits = re.sub(r"\D", "", text)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]
        if len(digits) != 10 or digits[0] in "01":
            return ""
        return digits

    def normalize_zip(raw):
        text = value({"v": raw}, "v").strip()
        if re.fullmatch(r"\d{5}-\d{4}", text):
            text = text.split("-", 1)[0]
        if re.fullmatch(r"\d{4}", text):
            text = "0" + text
        return text if re.fullmatch(r"\d{5}", text) else ""

    def normalize_name(raw):
        text = value({"v": raw}, "v").strip()
        if text.isupper() or text.islower():
            return text.title()
        return text

    def parse_updated(raw):
        text = value({"v": raw}, "v").strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(text, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {text!r}")

    def opted_out(raw):
        return value({"v": raw}, "v").strip().lower() in {"y", "yes", "true", "1"}

    def split_tags(raw):
        return {
            tag.strip().lower()
            for tag in re.split(r"[;,]", value({"v": raw}, "v"))
            if tag.strip()
        }

    prepared = []
    for index, row in enumerate(rows):
        email = normalize_email(row.get("email", ""))
        phone = normalize_phone(row.get("phone", ""))
        if not email and not phone:
            continue

        prepared.append({
            "index": index,
            "first_name": normalize_name(row.get("first_name", "")),
            "last_name": normalize_name(row.get("last_name", "")),
            "email": email,
            "phone": phone,
            "zip": normalize_zip(row.get("zip", "")),
            "source": value(row, "source").strip().lower(),
            "updated_dt": parse_updated(row.get("updated", "")),
            "opted_out": opted_out(row.get("opted_out", "")),
            "tags": split_tags(row.get("tags", "")),
        })

    # Build connected components so matching is transitive.
    parent = list(range(len(prepared)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    email_owner = {}
    phone_last_owner = {}
    for i, person in enumerate(prepared):
        if person["email"]:
            if person["email"] in email_owner:
                union(i, email_owner[person["email"]])
            else:
                email_owner[person["email"]] = i

        last = person["last_name"].casefold()
        if person["phone"] and last:
            key = (person["phone"], last)
            if key in phone_last_owner:
                union(i, phone_last_owner[key])
            else:
                phone_last_owner[key] = i

    groups = {}
    for i, person in enumerate(prepared):
        groups.setdefault(find(i), []).append(person)

    def select(group, field, require_valid=False):
        candidates = [
            person for person in group
            if person[field] and (not require_valid or person[field])
        ]
        if not candidates:
            return ""
        candidates.sort(key=lambda person: (
            person["source"] != "manual",
            -person["updated_dt"].timestamp(),
            person["index"],
        ))
        return candidates[0][field]

    output = []
    for group in sorted(groups.values(), key=lambda g: min(p["index"] for p in g)):
        latest = max(person["updated_dt"] for person in group)
        all_tags = set().union(*(person["tags"] for person in group))
        output.append({
            "first_name": select(group, "first_name"),
            "last_name": select(group, "last_name"),
            "zip": select(group, "zip"),
            "email": select(group, "email", require_valid=True),
            "phone": select(group, "phone", require_valid=True),
            "source": select(group, "source"),
            "tags": ";".join(sorted(all_tags)),
            "opted_out": "Y" if any(person["opted_out"] for person in group) else "N",
            "updated": latest.strftime("%Y-%m-%d"),
        })

    return output
